class StreamChecker {
    private final Node root = new Node();
    private final StringBuilder suffix = new StringBuilder();
    private int maxLength;

    public StreamChecker(String[] words) {
        for (String word : words) {
            maxLength = Math.max(maxLength, word.length());
            Node node = root;
            for (int i = word.length() - 1; i >= 0; i--) {
                int index = word.charAt(i) - 'a';
                if (node.next[index] == null) {
                    node.next[index] = new Node();
                }
                node = node.next[index];
            }
            node.word = true;
        }
    }

    public boolean query(char letter) {
        suffix.append(letter);
        if (suffix.length() > maxLength) {
            suffix.deleteCharAt(0);
        }

        Node node = root;
        for (int i = suffix.length() - 1; i >= 0; i--) {
            int index = suffix.charAt(i) - 'a';
            node = node.next[index];
            if (node == null) {
                return false;
            }
            if (node.word) {
                return true;
            }
        }
        return false;
    }

    private static final class Node {
        private final Node[] next = new Node[26];
        private boolean word;
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

class StreamChecker {
    private final int[][] next;
    private final int[] fail;
    private final boolean[] output;
    private int size;
    private int state;

    public StreamChecker(String[] words) {
        int nodeLimit = 1;
        for (String word : words) {
            nodeLimit += word.length();
        }
        next = new int[nodeLimit][26];
        fail = new int[nodeLimit];
        output = new boolean[nodeLimit];
        for (int[] row : next) {
            Arrays.fill(row, -1);
        }
        size = 1;

        for (String word : words) {
            int node = 0;
            for (int i = 0; i < word.length(); i++) {
                int c = word.charAt(i) - 'a';
                if (next[node][c] == -1) {
                    next[node][c] = size++;
                }
                node = next[node][c];
            }
            output[node] = true;
        }

        Queue<Integer> queue = new ArrayDeque<>();
        for (int c = 0; c < 26; c++) {
            if (next[0][c] == -1) {
                next[0][c] = 0;
            } else {
                queue.offer(next[0][c]);
            }
        }

        while (!queue.isEmpty()) {
            int node = queue.poll();
            output[node] = output[node] || output[fail[node]];
            for (int c = 0; c < 26; c++) {
                int child = next[node][c];
                if (child == -1) {
                    next[node][c] = next[fail[node]][c];
                } else {
                    fail[child] = next[fail[node]][c];
                    queue.offer(child);
                }
            }
        }
    }

    public boolean query(char letter) {
        state = next[state][letter - 'a'];
        return output[state];
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;

class StreamChecker {
    private final Node root = new Node();
    private List<Node> active = new ArrayList<>();

    public StreamChecker(String[] words) {
        for (String word : words) {
            Node node = root;
            for (int i = 0; i < word.length(); i++) {
                int c = word.charAt(i) - 'a';
                if (node.next[c] == null) {
                    node.next[c] = new Node();
                }
                node = node.next[c];
            }
            node.word = true;
        }
    }

    public boolean query(char letter) {
        int c = letter - 'a';
        Set<Node> nextStates = Collections.newSetFromMap(new IdentityHashMap<>());
        boolean matched = false;

        Node fromRoot = root.next[c];
        if (fromRoot != null) {
            nextStates.add(fromRoot);
            matched = matched || fromRoot.word;
        }

        for (Node node : active) {
            Node child = node.next[c];
            if (child != null && nextStates.add(child)) {
                matched = matched || child.word;
            }
        }

        active = new ArrayList<>(nextStates);
        return matched;
    }

    private static final class Node {
        private final Node[] next = new Node[26];
        private boolean word;
    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class StreamChecker {
    private final Map<Integer, Set<String>> wordsByLength = new HashMap<>();
    private final StringBuilder stream = new StringBuilder();
    private int maxLength;

    public StreamChecker(String[] words) {
        for (String word : words) {
            maxLength = Math.max(maxLength, word.length());
            wordsByLength.computeIfAbsent(word.length(), ignored -> new HashSet<>()).add(word);
        }
    }

    public boolean query(char letter) {
        stream.append(letter);
        if (stream.length() > maxLength) {
            stream.deleteCharAt(0);
        }

        for (Map.Entry<Integer, Set<String>> entry : wordsByLength.entrySet()) {
            int length = entry.getKey();
            if (length <= stream.length()) {
                String suffix = stream.substring(stream.length() - length);
                if (entry.getValue().contains(suffix)) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class StreamChecker {
    private static final long BASE = 911382323L;
    private final Map<Integer, Map<Long, List<String>>> wordsByLengthAndHash = new HashMap<>();
    private final StringBuilder stream = new StringBuilder();
    private int maxLength;

    public StreamChecker(String[] words) {
        for (String word : words) {
            maxLength = Math.max(maxLength, word.length());
            long hash = reversedHash(word);
            wordsByLengthAndHash
                    .computeIfAbsent(word.length(), ignored -> new HashMap<>())
                    .computeIfAbsent(hash, ignored -> new ArrayList<>())
                    .add(word);
        }
    }

    public boolean query(char letter) {
        stream.append(letter);
        if (stream.length() > maxLength) {
            stream.deleteCharAt(0);
        }

        long hash = 0L;
        for (int i = stream.length() - 1, length = 1; i >= 0; i--, length++) {
            hash = hash * BASE + stream.charAt(i);
            Map<Long, List<String>> bucket = wordsByLengthAndHash.get(length);
            if (bucket == null) {
                continue;
            }
            List<String> candidates = bucket.get(hash);
            if (candidates != null && matchesAny(candidates, length)) {
                return true;
            }
        }
        return false;
    }

    private long reversedHash(String word) {
        long hash = 0L;
        for (int i = word.length() - 1; i >= 0; i--) {
            hash = hash * BASE + word.charAt(i);
        }
        return hash;
    }

    private boolean matchesAny(List<String> candidates, int length) {
        int start = stream.length() - length;
        for (String word : candidates) {
            boolean same = true;
            for (int i = 0; i < length; i++) {
                if (stream.charAt(start + i) != word.charAt(i)) {
                    same = false;
                    break;
                }
            }
            if (same) {
                return true;
            }
        }
        return false;
    }
}
